-- Class notes synopsis batch 26: Vervain through Willow

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Vervain</strong> is a <strong>nervine</strong> herb added to psoriasis formulas when anxiety is present alongside the skin condition (David Hoffmann psoriasis formula).$$
WHERE id = 146;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Violet</strong> (Viola spp.) is a <strong>cooling</strong>, <strong>moistening</strong>, <strong>lymphatic</strong>, <strong>demulcent</strong>, and <strong>mild expectorant</strong> herb. Lymphatic for overall immune support; particular affinity for the chest — moves lymph in the thoracic region; for autoimmune conditions with fibromyalgia: gentle lymphatic alongside Cleavers. For <strong>sore throat</strong>: cooling and soothing demulcent; flowers used in syrups and teas. Violet oil: cooling, lymphatic; excellent for breast massage. <strong>Mucilage is extracted via cold water infusion.</strong>$$
WHERE id = 198;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>White Oak</strong> is an <strong>astringent</strong> herb used for <strong>diarrhea</strong>.$$
WHERE id = 2241;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>White Peony</strong> (Paeonia lactiflora) is a <strong>blood and yin tonic</strong>, <strong>anti-fibrotic</strong>, and <strong>mast cell stabilizer</strong> that nourishes the uterus and calms fibroblast production. Hormonal mechanism: reduces testosterone via the aromatase enzyme, increases progesterone, and regulates estrogen and prolactin. Foundational pairing: White Peony + <a href="?herb=78"><strong>Licorice</strong></a> (3:1 ratio) for reproductive disruption — together they improve insulin resistance and reduce elevated testosterone and prolactin (including prolactin elevated by risperidone). For <strong>fibroids</strong>: anti-fibrotic alongside <a href="?herb=20"><strong>Ashwagandha</strong></a> and <a href="?herb=225"><strong>Astragalus</strong></a>; combined with <a href="?herb=203"><strong>Turmeric</strong></a>. For <strong>PCOS</strong>: formula — <a href="?herb=33"><strong>Oregon Grape Root</strong></a> 30ml, <a href="?herb=78"><strong>Licorice</strong></a> 10ml, White Peony 30ml, <a href="?herb=167"><strong>Cinnamon</strong></a> 20ml, <a href="?herb=2229"><strong>Gotu Kola</strong></a> 30ml (4ml 2x/day); also in PMOS formula with Licorice, Cinnamon, and Gotu Kola to support the extracellular matrix. Hormonal support formula: <a href="?herb=78"><strong>Licorice</strong></a>, White Peony, <a href="?herb=42"><strong>Red Clover</strong></a>, <a href="?herb=190"><strong>Chasteberry</strong></a>, <a href="?herb=167"><strong>Cinnamon</strong></a> (2 tsp 3x/day). Reproductive tincture for thyroid/Hashimoto's: White Peony, <a href="?herb=167"><strong>Cinnamon</strong></a>, <a href="?herb=22"><strong>Burdock</strong></a>, <a href="?herb=78"><strong>Licorice</strong></a>, <a href="?herb=2229"><strong>Gotu Kola</strong></a>. Synergy with <a href="?herb=11"><strong>Reishi Mushroom</strong></a>. Blood building for cold constitution alongside <a href="?herb=1009"><strong>Dong Quai</strong></a>, <a href="?herb=20"><strong>Ashwagandha</strong></a>, <a href="?herb=134"><strong>Lemon Balm</strong></a>, <a href="?herb=885"><strong>Alfalfa</strong></a>, <a href="?herb=78"><strong>Licorice</strong></a>. For <strong>eczema</strong>: mast cell stabilizer, reduces allergic response in the skin. For <strong>perimenopause</strong>: hormone balancer. For female reproductive deficiency: anabolic stimulant; for female reproductive excess: anabolic cooler; for male reproductive deficiency: hormone and HPA axis support.$$
WHERE id = 2238;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Wild Cherry Bark</strong> is the <strong>primary herb for spasmodic cough</strong> — an <strong>antitussive</strong>, <strong>antispasmodic</strong>, and <strong>bronchodilator</strong> documented in the African American Materia Medica. Specifically for <strong>dry, hot, unproductive cough</strong> (sharp, painful); for productive coughs, focus on an expectorant instead. Antispasmodic for smooth muscles of the lungs and chest — can address even heart palpitations; for <strong>asthma</strong>: antitussive, bronchodilator, antispasmodic; for respiratory excess: cools overproduction. Added to <a href="?herb=54"><strong>Elecampane</strong></a> formula when cough is present; combined with <a href="?herb=45"><strong>Marshmallow</strong></a> and honey for cough syrup. <strong>Preparation</strong>: soak bark in water before tincturing to extract cherry vanilla flavor; delicious in honey syrup; percolation yields a more astringent quality.$$
WHERE id = 140;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Wild Ginger</strong> is a <strong>circulatory stimulant</strong> used for reproductive deficiency — indicated for both female and male reproductive deficiency conditions alongside <a href="?herb=1248"><strong>Ocotillo</strong></a>, <a href="?herb=25"><strong>Black Cohosh</strong></a>, and <a href="?herb=35"><strong>Poke Root</strong></a> (drop dose).$$
WHERE id = 2628;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Wild Indigo</strong> (Baptisia) is an <strong>antimicrobial</strong>, <strong>alterative</strong>, and <strong>innate immune stimulant</strong> herb. For <strong>infections</strong>: antimicrobial in wound wash; paired with <a href="?herb=35"><strong>Poke Root</strong></a> and <a href="?herb=26"><strong>Echinacea</strong></a> for bacterial infections in feeble individuals; immune support for microbial causes of diarrhea. Waste-eliminating alterative for wet constitution. For <strong>lymph/immune deficiency</strong>: supports innate immunity.$$
WHERE id = 23;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Wild Lettuce</strong> is a <strong>bitter</strong>, <strong>cooling</strong>, <strong>sedative</strong>, and <strong>analgesic</strong> herb — "one of the stronger herbal pain relievers." Very cold — not for already exhausted people. For <strong>pain</strong>: analgesic for bone aches and flu; for pain-induced insomnia; can blend with water and honey and roll into pills. For <strong>sleep and anxiety</strong>: sedative sleep aid; Lisa's sleep remedy as tea; sedative anxiolytic for anxiety; pairs well with <a href="?herb=2461"><strong>Jamaican Dogwood</strong></a> for recent injury and insomnia. With <a href="?herb=2461"><strong>Jamaican Dogwood</strong></a> and <a href="?herb=2228"><strong>Corydalis</strong></a>: TCM-inspired triplet targeting skeletal muscle and injuries. <strong>Identification</strong>: spine of spikes on the back of the leaf. <strong>Harvest</strong> when plant shoots stalk, before flowering. High alcohol needed for preservation.$$
WHERE id = 130;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Wild Yam</strong> is a <strong>smooth muscle antispasmodic</strong>, <strong>analgesic</strong>, and <strong>cholagogue</strong> herb — the better choice for smooth muscle relaxation (contrasted with the Jamaican Dogwood/Wild Lettuce/Corydalis triplet which targets skeletal muscle). For <strong>GI</strong>: smooth muscle relaxant for constipation; antispasmodic for stomach cramps and severe diarrhea; analgesic for sharp, spasmodic GI pain; useful acutely and preventively for gallstone spasm; promotes bile flow; upper GI excess formula alongside <a href="?herb=76"><strong>Fennel</strong></a>, <a href="?herb=129"><strong>Hops</strong></a>, <a href="?herb=136"><strong>Catnip</strong></a>, <a href="?herb=853"><strong>Silk Tassel</strong></a>. For <strong>pregnancy</strong>: smooth muscle antispasmodic; stomach cramps can translate into uterine cramps (miscarriage risk) — jump directly here if history of miscarriage; escalate from chamomile/peppermint if insufficient. For <strong>threatened miscarriage</strong>: 1P Wild Yam + 2P <a href="?herb=93"><strong>Cramp Bark</strong></a>; 1/2 tsp every 30 min for up to 4 hours, twice daily for up to 3 days; more effective than Cramp Bark alone. For <strong>female reproductive excess</strong> (short cycles &lt;24 days): alongside <a href="?herb=2627"><strong>Yellow Pond Lily</strong></a>, <a href="?herb=2626"><strong>Trillium</strong></a>, <a href="?herb=94"><strong>Black Haw</strong></a>, <a href="?herb=93"><strong>Cramp Bark</strong></a>. For <strong>male reproductive excess</strong>: with <a href="?herb=2627"><strong>Yellow Pond Lily</strong></a>, <a href="?herb=2626"><strong>Trillium</strong></a>, <a href="?herb=94"><strong>Black Haw</strong></a>, <a href="?herb=93"><strong>Cramp Bark</strong></a>.$$
WHERE id = 74;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Willow</strong> (White Willow, Salix alba) is an <strong>analgesic</strong>, <strong>anti-inflammatory</strong>, and <strong>astringent</strong> herb with a history of use exchanged between Cherokee nations and African Americans in North America. For <strong>pain and inflammation</strong>: analgesic and anti-inflammatory for rheumatism, gout, headaches, arthritis, sprains, and chronic musculoskeletal conditions; promotes healthy inflammation regulation; topical analgesic for rheumatoid arthritis; pain relief in the urinary system. For <strong>diarrhea</strong>: astringent; for influenza diarrhea. Anti-inflammatory for hot constitution. <strong>Preparation</strong>: most effective as decoction for arthritis (salicylic acid is hydrophilic); decoction + baking soda = buffered acid; astringent as tincture, analgesic as decoction; use in acute pain only — can be drying. Tip: David Winston recommends a tiny amount for pain; consider Devil's Claw, <a href="?herb=1597"><strong>Frankincense</strong></a> (Boswellia), or MSM for feline patients (gentler alternatives).$$
WHERE id = 87;
